import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as m,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"MAR 掩码自回归","description":"","frontmatter":{"title":"MAR 掩码自回归","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mar-masked-ar.md","filePath":"llm/mar-masked-ar.md","lastUpdated":1789023840000}'),h={name:"llm/mar-masked-ar.md"};function p(E,a,c,_,f,k){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="mar-掩码自回归" tabindex="-1">MAR 掩码自回归 <a class="header-anchor" href="#mar-掩码自回归" aria-label="Permalink to &quot;MAR 掩码自回归&quot;">​</a></h1><div class="epigraph"><p>不必先把图拧成码本下标。对连续视觉 token 做掩码，用扩散损失补洞，自回归结构仍在，量化可以拿掉。</p><footer>—— Li 等 Autoregressive Image Generation without Vector Quantization（MAR）；掩码先行见 Chang 等 MaskGIT</footer></div><p><a href="/llm/var-next-scale">上一课</a>仍在离散尺度上走。缺口是量化本身：<a href="/llm/vqgan">VQGAN</a> 的词表方便 softmax，但丢掉的信息回不来。MAR 把生成写成对连续 token 的掩码预测，补洞用扩散（或流）而不是词表 CE。后课统一模型默认：理解已经用连续 patch，生成也可以不必换一套码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MaskGIT 在离散码上随机掩码、并行预测被掩位置，推理逐步降掩码率。MAR 把「被掩位置」换成连续向量，用小型扩散头按条件（未掩可见 token + 位置）去噪出连续值。于是：没有码本崩溃，梯度是稠密的，和理解侧 <a href="/llm/vit-as-encoder">ViT</a> 连续特征更同构。</p><p>代价是不能再用标准 LM softmax 做统一词表；似然接口变成掩码 + 连续去噪，和纯文本 CE 仍异质。</p><p><span class="marginnote">掩码率日程决定从粗结构到细节，类似尺度课程，但不显式金字塔码。随机掩码与光栅顺序都是分解，只是条件集不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：对连续 tokenizer 输出随机掩码，扩散损失只加在被掩位置。推理：从全掩或噪声开始，逐步揭示。文本条件与 CFG 可加在扩散头上。评测对照同骨干的 VQ-AR：看细字与纹理是否因去掉量化而升，以及步数是否可接受。</p>',9)),(e(),n(A,null,{default:r(()=>[m(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIS%5B%22%E5%8F%AF%E8%A7%81%E8%BF%9E%E7%BB%AD%20token%22%5D%20--%3E%20HEAD%5B%22%E6%8E%A9%E7%A0%81%E6%89%A9%E6%95%A3%E5%A4%B4%22%5D%0A%20%20MASK%5B%22%E8%A2%AB%E6%8E%A9%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20HEAD%0A%20%20HEAD%20--%3E%20FILL%5B%22%E8%BF%9E%E7%BB%AD%E8%A1%A5%E6%B4%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可见 token 提供双向上下文（非因果），比 raster 更早看见四周，这是 MaskGIT 家族相对因果 AR 的几何优势。连续扩散补洞避免 softmax 对码字的硬选择，细节可以落在码本之间。与整图 <a href="/llm/ddpm">DDPM</a> 的差别是：条件来自部分已揭示的视觉 token，而不是只有时间 \\(t\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>统一到单一 Transformer 词表仍未完成。下一课 Janus / Show-o 在理解与生成之间拆或缝编码器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MAR 用掩码 + 连续扩散损失做图像生成，去掉 VQ 词表。</li><li>双向可见上下文利于结构；接口与文本 CE 仍不同。</li><li>理解用的连续 token 与这条生成路更近。</li><li>出处：Li 等 MAR；Chang 等 MaskGIT。</li></ul>',6))])}const M=l(h,[["render",p]]);export{T as __pageData,M as default};
